      "slide": 85,
      "text": "From the case study, explain 2 factors Sarah should consider when choosing a new location for Sublime Hairdressing.",
      "context": "Sarah is considering expanding Sublime Hairdressing by adding a make-up artist and beauty therapist. The current Stirling city-centre shop is in a busy location with ample parking, but it is small and the rent is high. Two other salons are nearby, although neither provides beauty or make-up services.",
